// Author: MiYu. Focused fixed-step unit avoidance checks on an open original-map area.
#include "session.h"
#include "setup.h"
#include <bit>
#include <cmath>
#include <iostream>

using namespace war3;
namespace {
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
WorldPoint point(float x,float y){return {real(x),real(y)};}
std::pair<float,float> openArea(ScriptSession& session){
    auto& world=*session.world();auto bounds=world.bounds();for(float y=number(bounds.minY)+256;y<number(bounds.maxY)-256;y+=128)for(float x=number(bounds.minX)+256;x<number(bounds.maxX)-256;x+=128){bool free=true;for(int dy=-160;dy<=160 && free;dy+=32)for(int dx=-192;dx<=192;dx+=32)if(!world.pathPointFree(point(x+dx,y+dy),24,PathMovement::Ground) || !world.pathPointFree(point(x+dx,y+dy),24,PathMovement::Air)){free=false;break;}if(!free)continue;for(auto& [id,u]:session.units())if(!u->removing && !u->hidden() && number(u->life)>0 && std::hypot(number(u->x)-x,number(u->y)-y)<384+std::max(0.f,u->collision)){free=false;break;}if(free)return {x,y};}throw std::runtime_error("No open test area on selected map");
}
}
int wmain(int argc,wchar_t** argv){try{
    if(argc!=3 && argc!=4)throw std::runtime_error("Usage: war3_movement_avoidance_tests <data-root> <map> [windwalk]");auto mode=argc==4?std::wstring_view(argv[3]):std::wstring_view{};if(!mode.empty() && mode!=L"windwalk")throw std::runtime_error("Unknown movement avoidance mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto invoke=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto player=invoke("Player",{vm.integer(0)});auto [x,y]=openArea(session);auto spawn=[&](float px,float py){auto handle=invoke("CreateUnit",{player,vm.integer(int(ObjectData::code("hfoo"))),vm.real(real(px)),vm.real(real(py)),vm.real(real(0))});require(session.units().contains(handle.bits),"Unit creation failed");auto u=session.units().at(handle.bits);u->collision=16;u->moveSpeed=real(256);return handle;};auto route=[&](jass::Value unit,float tx,float ty){auto u=session.units().at(unit.bits);u->route={point(tx,ty)};u->waypoint=0;u->currentOrder=851986;u->pathingRevision=session.world()->blockingRevision();};auto remove=[&](jass::Value unit){invoke("RemoveUnit",{unit});};
    if(mode==L"windwalk"){auto pass=[&](bool phasedMover,bool building,bool generic,bool expire=false){auto a=spawn(x-64,y),b=spawn(x,y);auto walker=session.units().at(phasedMover?a.bits:b.bits);UnitBuff buff;buff.id=ObjectData::code(generic?"Bivs":"BOwk");buff.kind=generic?BuffKind::Invisibility:BuffKind::WindWalk;buff.remaining=expire?.0625:5;buff.fadeRemaining=generic?0:1;walker->buffs[buff.id]=buff;session.units().at(b.bits)->building=building;route(a,x+120,y);float minimum=1e9f;for(unsigned i=0;i<16;++i){session.advance(1./32);auto first=session.units().at(a.bits),second=session.units().at(b.bits);minimum=std::min(minimum,std::hypot(number(first->x)-number(second->x),number(first->y)-number(second->y)));}float finish=number(session.units().at(a.bits)->x);remove(a);remove(b);return std::pair{minimum,finish};};auto forward=pass(true,false,false),reverse=pass(false,false,false),ordinary=pass(true,false,true),structure=pass(true,true,false),expired=pass(true,false,false,true);require(forward.first<16 && forward.second>x+20,"Wind Walk mover was blocked by another unit");require(reverse.first<16 && reverse.second>x+20,"Other unit was blocked by a Wind Walk unit");require(ordinary.first>=31.95f,"Ordinary invisibility incorrectly disabled collision");require(structure.first>=31.95f,"Wind Walk bypassed a building");require(expired.first>=31.95f,"Expired Wind Walk retained collision bypass");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS windwalk_unit_collision_and_building_boundary\n";return 0;}
    auto a=spawn(x-64,y),b=spawn(x+64,y),independent=spawn(x-64,y+120);route(a,x+160,y);route(b,x-160,y);route(independent,x+160,y+120);float minimum=1e9f,sideways=0;for(int i=0;i<32;++i){session.advance(1./32);auto left=session.units().at(a.bits),right=session.units().at(b.bits);minimum=std::min(minimum,std::hypot(number(left->x)-number(right->x),number(left->y)-number(right->y)));sideways=std::max({sideways,std::abs(number(left->y)-y),std::abs(number(right->y)-y)});}require(minimum>=31.95f,"Head-on units overlapped");require(sideways>1,"Head-on units did not steer around each other");require(number(session.units().at(independent.bits)->x)>x+40,"Independent movement was blocked");require(number(session.units().at(a.bits)->x)>x-40 || number(session.units().at(b.bits)->x)<x+40,"Head-on units failed to move");remove(a);remove(b);remove(independent);std::cout<<"PASS head_on_and_independent\n";
    a=spawn(x-120,y);b=spawn(x,y);auto walker=session.units().at(a.bits);walker->route={point(x,y),point(x+120,y)};walker->waypoint=0;walker->currentOrder=851986;walker->pathingRevision=session.world()->blockingRevision();float clearance=1e9f;for(unsigned i=0;i<192 && !walker->route.empty();++i){session.advance(1./32);clearance=std::min(clearance,std::hypot(number(walker->x)-number(session.units().at(b.bits)->x),number(walker->y)-number(session.units().at(b.bits)->y)));}require(clearance>=31.95f,"Intermediate waypoint bypass overlapped blocker");require(walker->route.empty() && number(walker->x)>x+110,"Occupied intermediate waypoint stalled route");remove(a);remove(b);std::cout<<"PASS occupied_intermediate_waypoint\n";
    a=spawn(x-120,y);b=spawn(x,y);route(a,x,y);auto finalBlocked=session.units().at(a.bits);for(unsigned i=0;i<96;++i)session.advance(1./32);require(!finalBlocked->route.empty() && std::hypot(number(finalBlocked->x)-x,number(finalBlocked->y)-y)>=31.95f,"Occupied final destination was discarded or crossed");remove(a);remove(b);std::cout<<"PASS occupied_final_destination_preserved\n";
    a=spawn(x-120,y);b=spawn(x,y);std::vector<PathCell> wall;for(int dy=-160;dy<=160;dy+=32)if(auto cell=session.world()->pathCell(x+64,y+dy))wall.push_back({*cell,2});session.world()->footprint(wall,true);auto fenced=session.units().at(a.bits);fenced->route={point(x,y),point(x+120,y)};fenced->waypoint=0;fenced->currentOrder=851986;fenced->pathingRevision=session.world()->blockingRevision();for(unsigned i=0;i<96;++i){auto before=point(number(fenced->x),number(fenced->y));session.advance(1./32);require(session.world()->pathSegmentFree(before,{fenced->x,fenced->y},fenced->collision,PathMovement::Ground),"Intermediate bypass crossed blocked terrain");}require(fenced->route.empty()?std::hypot(number(fenced->x)-(x+120),number(fenced->y)-y)<1:std::hypot(number(fenced->route.back().x)-(x+120),number(fenced->route.back().y)-y)<1,"Blocked route lost its final destination");session.world()->footprint(wall,false);remove(a);remove(b);std::cout<<"PASS occupied_waypoint_terrain_barrier\n";
    a=spawn(x,y);b=spawn(x,y);route(a,x-120,y);route(b,x+120,y);session.advance(.125);auto left=session.units().at(a.bits),right=session.units().at(b.bits);require(number(left->x)<x-1 && number(right->x)>x+1,"Overlapping units could not separate");remove(a);remove(b);std::cout<<"PASS overlap_escape\n";
    a=spawn(x-64,y);b=spawn(x,y);session.units().at(a.bits)->pathing=false;route(a,x+120,y);session.advance(.5);require(number(session.units().at(a.bits)->x)>x+20,"Unit without pathing was blocked by another unit");remove(a);remove(b);std::cout<<"PASS pathing_disabled\n";
    a=spawn(x-64,y);b=spawn(x,y);session.units().at(a.bits)->movementType="fly";route(a,x+120,y);session.advance(.5);require(number(session.units().at(a.bits)->x)>x+20,"Air unit was blocked by ground unit");remove(a);remove(b);std::cout<<"PASS air_ground_layers\n";
    a=spawn(x-64,y);route(a,x+160,y);auto retry=session.units().at(a.bits);auto previousRevision=retry->pathingRevision;std::vector<jass::Value> pending{a};for(unsigned i=0;i<79;++i){auto unit=spawn(x-64,y);route(unit,x+160,y);pending.push_back(unit);}auto progress=spawn(x-190,y);route(progress,x-150,y);std::vector<PathCell> blockers;for(int dy=-288;dy<=288;dy+=32)for(int dx=-288;dx<=288;dx+=32)if(auto cell=session.world()->pathCell(x+160+dx,y+dy))blockers.push_back({*cell,2});session.world()->footprint(blockers,true);auto blockedRevision=session.world()->blockingRevision();require(blockedRevision!=previousRevision,"Test footprint did not block the route");auto attempted=[&]{return size_t(std::count_if(pending.begin(),pending.end(),[&](auto unit){return session.units().at(unit.bits)->routeRetryWorldRevision==session.world()->pathingRevision();}));};session.advance(1./32);require(attempted()<=4,"Replan tick exceeded its global budget");require(session.units().at(progress.bits)->routeRetryWorldRevision!=session.world()->pathingRevision() && number(session.units().at(progress.bits)->x)>x-189,"Unit waiting for replan failed to follow its clear old route");remove(progress);for(unsigned i=0;i<128 && attempted()<pending.size();++i)session.advance(1./32);require(attempted()==pending.size(),"Replan queue starved higher handles");require(retry->routeRetryWorldRevision==session.world()->pathingRevision() && retry->pathingRevision==previousRevision && retry->waypoint==0 && retry->route.size()==1 && number(retry->route.back().x)==x+160,"Unreachable replan lost its original route");for(size_t i=1;i<pending.size();++i)remove(pending[i]);session.world()->footprint(blockers,false);for(unsigned i=0;i<128 && retry->pathingRevision!=session.world()->blockingRevision();++i)session.advance(1./32);require(retry->pathingRevision==session.world()->blockingRevision() && !retry->route.empty(),"Route was not recovered after obstacle removal");remove(a);std::cout<<"PASS blocked_replan_retains_and_recovers\n";
    a=spawn(x,y);route(a,x+120,y);auto outside=session.units().at(a.bits);outside->x=real(1e30f);session.advance(1./32);require(number(outside->x)==1e30f && !outside->route.empty(),"Out-of-map side step moved or lost its order");auto marker=session.world()->pathCell(x+120,y);require(marker.has_value(),"Missing test path cell");std::vector<PathCell> one{{*marker,2}};session.world()->footprint(one,true);for(unsigned i=0;i<128 && outside->routeRetryWorldRevision!=session.world()->pathingRevision();++i)session.advance(1./32);require(!outside->route.empty() && outside->pathingRevision!=session.world()->blockingRevision() && outside->routeRetryWorldRevision==session.world()->pathingRevision(),"Out-of-map route retry lost its order");session.world()->footprint(one,false);remove(a);std::cout<<"PASS outside_map_bounded_retry\n";
    require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
